import { Injectable } from '@angular/core';
import { CommunicationService } from '../../../services/communication/communication.service';
import { MYFILES_CS_EVENTS } from '../../../../userpanel/utility/user-panel-constants';
import { advanceFiler } from '../../../../userpanel/interfaces/advance-search.interface';
import { ErrorHandlerUtil } from '../../../../userpanel/utility/error-handler.util';

@Injectable({
    providedIn: 'root'
})
export class FileSearchService {

    constructor(private readonly cs: CommunicationService) { }

    handleSearchFilesEvent(dialogRef: any): { reset: boolean } {
        if (dialogRef?.componentInstance?.actiontype == 'DOWNLOAD') { return { reset: false } }
        return { reset: true };
    }

    handleSearchElasticEvent(data: any): { isElasticSearch: boolean, shouldUpdate: boolean } {
        if (!data?.jFilter?.cSearch) {
            return { isElasticSearch: true, shouldUpdate: false };
        }
        // this.getSummaryOfElasticSearch(data?.jFilter) // This was empty in component
        return { isElasticSearch: true, shouldUpdate: true };
    }

    handleSearchingEvent(data: any): boolean {
        return data.data.isSearch;
    }

    changeBrdcrumbSearch(index: number, brdcrumbsearch: any[], jFilter: advanceFiler): { newBrdcrumb: any[], nBundleid: string | null } {
        if (index > -1) {
            const newBrdcrumb = brdcrumbsearch.filter((e, i) => i <= index);
            let nBundleid = newBrdcrumb.length ? newBrdcrumb[newBrdcrumb.length - 1]["nBundleid"] : 0;

            this.cs.callFunction({ event: MYFILES_CS_EVENTS.CHANGE_SEARCH_SECTION, nBundleid: nBundleid });
            return { newBrdcrumb, nBundleid };
        } else {
            this.cs.callFunction({ event: MYFILES_CS_EVENTS.SEARCH_BUNDLES_CLEAR });

            setTimeout(() => {
                this.cs.callFunction({ event: MYFILES_CS_EVENTS.CHANGE_SEARCH_SECTION, nBundleid: null });
                this.cs.callFunction({ event: MYFILES_CS_EVENTS.UPDATE_SEARCH_URL, jFilter: jFilter }); // Check if jFilter updates are needed before this
            }, 100);
            return { newBrdcrumb: [], nBundleid: null };
        }
    }

    elasticFileSort(fileList: any[], sortby: string, order: boolean): any[] {
        const cSortby = this.getSortkey(sortby) || sortby;

        try {
            return [...fileList].sort((a, b) => {
                const valA = a[cSortby];
                const valB = b[cSortby];

                if (valA == null && valB == null) return 0;
                if (valA == null) return order ? -1 : 1;
                if (valB == null) return order ? 1 : -1;

                if (Array.isArray(valA) && Array.isArray(valB)) {
                    const len = Math.min(valA.length, valB.length);
                    for (let i = 0; i < len; i++) {
                        const aItem = valA[i];
                        const bItem = valB[i];

                        const nA = Number(aItem), nB = Number(bItem);
                        let cmp: number;
                        if (!isNaN(nA) && !isNaN(nB)) {
                            cmp = nA - nB;
                        } else {
                            cmp = String(aItem).localeCompare(String(bItem));
                        }
                        if (cmp !== 0) {
                            return order ? cmp : -cmp;
                        }
                    }
                    return order
                        ? valA.length - valB.length
                        : valB.length - valA.length;
                }

                if (typeof valA === 'number' && typeof valB === 'number') {
                    return order
                        ? valA - valB
                        : valB - valA;
                }

                const sA = String(valA).toLowerCase();
                const sB = String(valB).toLowerCase();
                return order
                    ? sA.localeCompare(sB)
                    : sB.localeCompare(sA);
            });

        } catch (error) {
            console.log('Error sorting fileList:', error);
            return fileList;
        }
    }

    private getSortkey(sortby: string) {
        if (sortby == 'cBundletag') {
            return 'sorted_bundletag';
        }
        else if (sortby == 'cTab') {
            return 'sorted_tab';
        }
        else if (sortby == 'cName') {
            return 'sorted_name';
        }
        else if (sortby == 'cPage') {
            return 'sorted_page';
        }
        else if (sortby == 'cExhibitno') {
            return 'sorted_exhibitno';
        }
        return sortby;
    }
}
