import { ChangeDetectorRef, Component, CUSTOM_ELEMENTS_SCHEMA, EventEmitter, Input, Output } from '@angular/core';
import { SectionRes } from '../../../../../adminpanel/interfaces/bundlemanage.interface';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { MatExpansionModule } from '@angular/material/expansion';
import { EmptyComponent } from '../../../../../shared/components/empty/empty.component';
import { CommonModule } from '@angular/common';
import { AvatarComponent } from '../../../../../shared/components/avatar/avatar.component';
import { MyfileService } from '../../../../../shared/services/myfile/myfile.service';
import { TableComponent } from '../../../../../shared/components/myfiles/table/table.component';
import { FilehaderComponent } from '../../../../../shared/components/myfiles/filehader/filehader.component';
import { FilecolumnService } from '../../../../../shared/services/filecolumn/filecolumn.service';
import { advanceFiler } from '../../../../interfaces/advance-search.interface';
import { Subscription } from 'rxjs';
import { HeaderService } from '../../../../../core/services/header/header.service';
import { CommunicationService } from '../../../../../shared/services/communication/communication.service';
import { highlightModeType, toolEvents } from '../../../../../pdf/interfaces/pdf.interface';

@Component({
    selector: 'contacts',
    standalone: true,
    imports: [CommonModule, EmptyComponent, MatExpansionModule, IconComponent, AvatarComponent, TableComponent, FilehaderComponent],
    templateUrl: './contacts.component.html',
    styleUrl: './contacts.component.scss',
    schemas: [CUSTOM_ELEMENTS_SCHEMA]
})
export class ContactsComponent {

    @Input() isLink: highlightModeType = null;
    @Output() emitEvent: EventEmitter<toolEvents> = new EventEmitter();
    @Input() nSectionid: string;
    @Input() nCaseid: string;
    @Input() nBundleid: string;
    @Output() viewFile: EventEmitter<any> = new EventEmitter();
    List: any = []
    reqcols: any = {};
    isLoading: boolean = false;
    private evsubscription: Subscription;
    @Input() jFilter: advanceFiler;
  @Input() reqcolKeys = [];
    constructor(private mfs: MyfileService, private cdr: ChangeDetectorRef,
        private fcs: FilecolumnService, private cs: CommunicationService, public headSearvice: HeaderService) {
        this.reqcols = fcs.reqcols;
        this.checkEventSub();
    }

    ngOnInit(): void {
        this.reqcols = this.fcs.reqcols;
        console.log('req cols', this.reqcols);

        //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
        //Add 'implements OnInit' to the class.
        this.getContactlist();

        
    }

    async getContactlist() {
        this.isLoading = true;
        let res = await this.mfs.getContactList(this.nCaseid, this.nSectionid, this.nBundleid)
        this.isLoading = false;
        this.List = res;

        this.cdr.detectChanges();
    }

    async getContactfiles(x) {
        if (x.tablelist && x.tablelist.length) {
            return;
        }
        x["isLoading"] = true;
        let res = await this.mfs.getFileList(this.nSectionid, x.nContactid, null, null, this.jFilter)
        x["isLoading"] = false;
        x.tablelist = res && res.length ? res : [];
        this.cdr.detectChanges();
    }

    changeTable(event: any, x) {
        if (event == 'VIEW') {
            this.viewFile.emit(x);
        }
    }


    async checkEventSub() {
        this.evsubscription = this.cs.functionCalled$.subscribe(async (data) => {

            if (data?.event == 'SEARCH_ELASTIC') {
                return;
            }
            if (data.event == 'SEARCH_FILES') {
                try {
                    this.jFilter = data?.jFilter;
                    this.cdr.detectChanges();
                } catch (error) {
                }
                if (this.headSearvice.isGlobalSearch) {
                    this.cs.callFunction({ event: 'SEARCHING', data: { isSearch: true } });
                } else {

                    this.cs.callFunction({ event: 'SEARCHING', data: { isSearch: false } });
                }
            } if (data.event == 'CLEAR-SELECTION') {
                this.List.forEach(element => {
                    element.issuelist.forEach(ele => {
                        ele.tablelist?.forEach(f => {
                            f.cIscheck = false;
                        })
                    })
                })
                this.cdr.detectChanges();
            }
        })
    }

    ngOnDestroy(): void {
        //Called once, before the instance is destroyed.
        //Add 'implements OnDestroy' to the class.
        this.evsubscription?.unsubscribe();
    }

    eventEmit(event: toolEvents, nBundledetailid: string) {
        this.emitEvent.emit({ event: event.event, data: { nBundledetailid, ...event.data } });
    }
}
