  changeTypes(x) {
    if (this.isElasticSearch) { return; }
    if (x.cFiletype == this.cFiletype) {
      return;
    }

    if (this.cFiletype != 'ALL') { this.isCheckAll = false; }
    x.active = !x.active;
    if (this.headSearvice.isGlobalSearch) {
      this.getFileSearch(1, x.cFiletype)
    } else {

      this.getFileList(1, x.cFiletype)
    }
  }

  loadMoreFiles() {
    if (this.isLoading || this.noMoreFiles) return;
    this.nPage++;
    console.warn('Loading more data, page:', this.nPage);
    this.getFilesElasticSearch(this.jFilter);
  }

  async getFilesElasticSearch(jFilter: advanceFiler) {
    if (!jFilter.cSearch) {
      return;
    }
    // if (this.isLoading) return;
    this.isLoading = true;
    this.cdr.detectChanges();

    const isCaseSensitive = jFilter.cMatchCase == 'E';
    const isStartWith = jFilter.cMatchCase == 'S';
    const isWholeWord = jFilter.cMatchCase == 'E';
    const nBundleid = jFilter.cLocation == 'A' ? null : jFilter.nBundleid;

    const requestToken = ++this.currentSearchToken; // increment token
    try {
      this.fileLoader(true);
      const res = await this.advanceSearchService.search(
        jFilter.cSearch,
        this.nCaseid,
        isCaseSensitive,
        isStartWith,
        isWholeWord,
        this.nPage,
        this.pageSize,
        jFilter?.jIssues,
        jFilter?.jImpact,
        jFilter?.jRelevance,
        jFilter?.jMarkup,
        nBundleid,
        this.nSectionid,
        this.cFoldertype
      );
      if (requestToken !== this.currentSearchToken) {
        console.warn('Ignoring outdated response');
        return;
      }
      if (res.msg == 1) {
        this.isLoading = false;
        this.loading = false;
        if (this.nPage == 1) {
          this.fileList = [];
        }
        const data = res.data || [];
        if (data?.length) {
          this.fileList = [...this.fileList, ...data];
          this.noMoreFiles = false;
        } else {
          this.noMoreFiles = true;
        }
      } else {
        this.isLoading = false;
        this.loading = false;
        this.tostServce.error(`Error ${res?.error}`);
      }
    } catch (error) {
      if (requestToken === this.currentSearchToken) {
        this.isLoading = false;
        this.loading = false;
        this.viewport?.checkViewportSize();
        this.tostServce.error(`Error ${error}`);
      }
    } finally {
      this.fileLoader(false);
      if (requestToken === this.currentSearchToken) {
        this.isLoading = false;
        this.loading = false;
        this.headerloading = true;
        this.isEmptyevent.emit(this.fileList.length);
        this.viewport?.checkViewportSize();
        setTimeout(() => {
          this.appendFileheader();
          this.headerloading = false;
        }, 500);
        this.cdr.detectChanges();
      }
    }
  }


  async getFileList(pageNumber, cFiletype?, isForcely?: boolean) {

    if (this.headSearvice.isGlobalSearch && !isForcely) { return; } // && this.jFilter?.cWithin == 'I'
    if (this.cFoldertype == 'ALL') {
      this.fileList = [];
      this.loading = false;
      this.isEmptyevent.emit(this.fileList.length);
      return;
    }
    if (!this.headSearvice.isGlobalSearch && !this.nBundleid && this.cFoldertype == 'MB' && !this.jfileFilter?.length) { return; }
    this.cFiletype = cFiletype ? cFiletype : 'ALL';
    this.Lpageno = pageNumber;
    this.loading = true;
    if (cFiletype && this.fileTypes.length) {
      this.fileTypes.forEach(e => { if (e.cFiletype != cFiletype) { e["active"] = false } });
    }

    if (!cFiletype) {
      this.cSortby = 'cTab';
      this.cLastOtype = 'flag2';
    }
    try {

      const requestToken = ++this.currentSearchToken; // increment token

      const mdl: bundleDetailReq = {
        nSectionid: this.nSectionid, nBundleid: this.nBundleid ? this.nBundleid : null, pageNumber: pageNumber
        , cSearch: '', cFiletype: cFiletype ? cFiletype : 'ALL', cSortby: this.cSortby, cSorttype: this[this.cLastOtype] ? 'DESC' : 'ASC'
        , nStarttabid: this.nStarttabid, nEndtabid: this.nEndtabid, jFilter: JSON.stringify(this.jfileFilter || [])
      }
      if (!pageNumber || pageNumber === 1) this.fileList = [];
      this.fileLoader(true);
      const res: bundleDetailRes[] = await this.myfileS.bundleDetailList(mdl);
      if (requestToken !== this.currentSearchToken) {
        console.warn('Ignoring outdated response');
        return;
      }
      this.fileLoader(false);

      if (pageNumber == 1) {
        this.getBundleLinks(mdl);
      } else {
        res
          .filter(e => e.nBundledetailid && this.filelinks.some(x => e.nBundledetailid === x.nBDid))
          .forEach(e => {
            let file = this.filelinks.find(x => e.nBundledetailid === x.nBDid);
            e.fact = file.f; e.doc = file.d; e.web = file.w; e.flink = file.fl; e.share = file.sh;
          });
      }
      let cIscheck = false;
      if (mdl.nBundleid && res.length) {
        cIscheck = await this.fxComponent.checkFolderForfile(mdl.nBundleid);
      }
      if (!cIscheck && res.length) {
        for (let i = 0; i < res.length; i++) {
          res[i]["cIscheck"] = await this.fxComponent.checkFolderForfile(res[i].nBundleid);
        }
      }
      res.forEach(e => { e["cIscheck"] = cIscheck ? cIscheck : this.isCheckAll ? this.isCheckAll : e["cIscheck"]; });


      if (pageNumber === 1) {
        this.fileList = res;
      }
      else {
        this.fileList = [...this.fileList, ...res];
      }
      if (this.presentDocType) {
        this.fileList.forEach((x) => x.cIscheck = this.selectedBundleDetails.includes(x.nBundledetailid) ? true : x.cIscheck)
      }
      if (this.nSelectedFilesid && this.nSelectedFilesid.length) {
        this.fileList.forEach((x) => x.cIscheck = this.nSelectedFilesid.some(i => i.id == x.nBundledetailid ? true : x.cIscheck))
      }
      if (this.nSelectedFolderid && this.nSelectedFolderid.length) {
        // this.fileList.map((x) => x.cIscheck = this.nSelectedFolderid.some(i => i.id == x.nBundleid) ? true : x.cIscheck)
        if (this.nSelectedFolderid.some(i => i.id == this.nBundleid)) {
          this.isCheckAll = true;
          this.showCheckall = true;
        }
      }
      this.loading = false

      Promise.resolve().then(() => {
        this.isEmptyevent.emit(this.fileList.length);
        this.viewport?.checkViewportSize();
        if (res.length) {
          this.changeFiles.emit('GET_BUNDLE_LIST');
        }
        if (pageNumber === 1 && (!cFiletype || cFiletype == '' || cFiletype == 'ALL')) {
          let jFilter = {
            cMatchCase: 'C', cSearch: '', cLocation: 'A', cWithin: this.cf.searchin, contentType: 'All',
            jFTypes: [], nCaseid: this.headSearvice.nCaseid || this.headSearvice?.Casedetail?.nCaseid,
          } as advanceFiler;

          jFilter = Object.assign(jFilter, { fileFilter: this.jfileFilter || [] })
          this.getFiletypes(jFilter)
          this.appendFileheader();
        }
        this.cdr.detectChanges();
        if (this.cf.paginationIDs.length && !this.fileList.find(x => x["cIsPaginate"])) {
          this.fileList.filter(e => this.cf.paginationIDs.includes(e.nBundledetailid)).map(e => e.cIsPaginate = true);
        }
      });

    } catch (error) {
      this.isLoading = false;
      this.loading = false;
      this.viewport?.checkViewportSize();
      this.tostServce.error(`Error ${error}`);
      this.isEmptyevent.emit(this.fileList.length);
    }

  }


