  constactEvent(event) {
    if (event.event == 'SELECTED') {
      if (event.data.nBundledetailid) {
        if (!event.data?.cIscheck) {
          if (this.nSelectedFilesid && this.nSelectedFilesid.length) {
            let ind = this.nSelectedFilesid.findIndex(i => i.id == event.data.nBundledetailid)
            if (ind > -1) {
              this.nSelectedFilesid.splice(ind, 1);
            }
          }
        } else {
          if (this.nSelectedFilesid) {
            let ind = this.nSelectedFilesid.findIndex(i => i.id == event.data.nBundledetailid)
            if (ind == -1) {
              this.nSelectedFilesid.push({ id: event.data.nBundledetailid, bid: this.nBundleid });
            }
          } else {
            this.nSelectedFilesid = [];
            this.nSelectedFilesid.push({ id: event.data.nBundledetailid, bid: this.nBundleid });
          }
        }
      }
      this.OnEvent.emit({ event: 'SELECTED', data: { jBids: [], cIscheck: true } });
    }
  }

