  calculateViewportTopOffset() {
    let element: any = this.viewport.elementRef.nativeElement;
    let offset = 0;

    while (element) {
      offset += element.offsetTop;
      element = element.offsetParent;
    }

    this.viewportTopOffset = offset;
  }

