  async updateFileTab(nBundledetailid, cTab) {

    let ind = this.fileList.findIndex(e => e.nBundledetailid == nBundledetailid)
    // if (cTab.trim() == this.fileList[ind].cTab.trim()) {
    // return;
    // }
    let bundle = [];
    if (this.tabEditMode == 'A') {
      bundle = this.incrementLastInteger(nBundledetailid, cTab);
    } else {
      bundle = [[nBundledetailid, cTab]];
    };
    const mdl: updateFiletab = { nBundledetailid: nBundledetailid, bundle: '[]', cTab: cTab, nBundleid: this.nBundleid, nSectionid: this.nSectionid, bisAutoassign: this.tabEditMode == 'A' ? true : false };
    let res: boolean = await this.myfileS.updateTab(mdl);
    if (res) {
      for (let file of bundle) {
        ind = this.fileList.findIndex(e => e.nBundledetailid == file[0])
        this.fileList[ind]["cTab"] = file[1];
      }
      if (this.tabEditMode == 'A') {
        this.reqcols.tab["edit"] = false;
      }
      this.changeB = !this.changeB;
      this.cdr.detectChanges();
    }
  }


  incrementLastInteger(nBundledetailid, value) {
    const match = value.match(/(\d+)(?!.*\d)/);
    if (match || value == '') {
      const incrementedValues = [];
      const ind = this.fileList.findIndex(e => e.nBundledetailid == nBundledetailid);
      const bundle = this.fileList.filter((e, index) => index >= ind).map(e => [e.nBundledetailid, e.cTab]);
      if (value != '') {
        const lastInt = parseInt(match[1], 10);
        const base = value.slice(0, match.index);
        for (let i = 0; i < bundle.length; i++) {
          incrementedValues.push([bundle[i][0], `${base}${lastInt + i}`]);
        }
      } else {
        for (let i = 0; i < bundle.length; i++) {
          incrementedValues.push([bundle[i][0], ``]);
        }
      }
      return incrementedValues;
    }
    return [];
  }


