  viewFile(x) {
    this.fxComponent.viewAssigntab = false;
    if (!this.fxComponent.isPreview) {
      if (!this.cf.viewlist.length) {
        this.cf.viewlist.push(x);
        this.cf["viewlist"][0]["active"] = true;
        this.fxComponent.isPreview = !this.fxComponent.isPreview;
      } else if (this.cf.viewlist.length == 1) {
        if (this.cf.viewlist[0].nBundledetailid == x.nBundledetailid) {
          this.cf.viewlist = [x];
          return
        }
        this.cf["viewlist"] = [x];
        this.cf["viewlist"][0]["active"] = true;
        this.fxComponent.isPreview = !this.fxComponent.isPreview;
      } else {
        const ind = this.cf["viewlist"].findIndex(e => e["active"]);
        if (ind > -1) {
          this.cf["viewlist"][0]["active"] = true;
        }
      }
    } else {
      if (!this.cf.viewlist.length) {
        this.cf.viewlist.push(x);
        this.cf["viewlist"][0]["active"] = true;
      } else if (this.cf.viewlist.length && this.cf.viewlist.find(e => e["nBundledetailid"] == x.nBundledetailid)) {
        const ind = this.cf.viewlist.findIndex(e => e["nBundledetailid"] == x.nBundledetailid);
        this.cf.viewlist.splice(ind, 1);
        // return;
      } else if (this.cf.viewlist.length && this.cf.viewlist.find(e => e["nBundledetailid"] != x.nBundledetailid)) {
        if (this.cf.viewlist.length == 1) {
          this.cf.viewlist = [x];
          this.cf.viewlist = [x];
          this.cf["viewlist"][0]["active"] = true;
        } else {
          const ind = this.cf["viewlist"].findIndex(e => e["active"]);
          if (ind > -1) {
            this.cf["viewlist"][ind] = x
            this.cf["viewlist"][ind]["active"] = true;
            this.cf["viewlist"].forEach((item, index) => {
              if (index != ind) {
                item["active"] = false;
              }
            })
          }
        }
      }
    }

    if (this.cf.viewlist.length) {
      this.changeFiles.emit('VIEW');
    }
  }

