  checkDuplicate(ids: string): string[] {
    // Parse the input string to extract numerical file IDs
    const fileIds = ids.replace(/{|}/g, '').split(',').map(String);

    if (this.headSearvice.isGlobalSearch) { return fileIds }
    // Filter the IDs to find those that are not present in fileList
    const nonExistingIds = fileIds.filter(id =>
      !this.fileList.some(file => file.nBundledetailid === id)
    );
    // Return the IDs that do not exist
    return nonExistingIds;
  }


