  customSort(obj) {
    // Convert object to an array of entries with their keys
    let entries: any = Object.entries(obj).map(([key, value]) => ({
      key,
      ...(typeof value === 'object' && value !== null ? value : {})
    }));

    // Sort the array based on id order, placing unmatched ones at the end
    entries.sort((a, b) => {
      return a.order - b.order
    });
    return entries.map(e => e.key);

    // // Convert back to an object
    // return Object.fromEntries(entries.map(({ key, ...rest }) => [key, rest]));
  }

