import { Component, EventEmitter, Input, OnChanges, OnDestroy, OnInit, Output, SimpleChanges } from '@angular/core';
import { IconComponent } from '../../icon/icon.component';
import { SectionRes } from '../../../../adminpanel/interfaces/bundlemanage.interface';
import { CommonModule } from '@angular/common';
import { MyfileService } from '../../../services/myfile/myfile.service';
import { MatTooltipModule } from '@angular/material/tooltip';
import { Subscription } from 'rxjs';
import { CommunicationService } from '../../../services/communication/communication.service';

interface OpenFolderItem {
  id: string | number;
  path: string[];
  isactive?: boolean;
}

@Component({
  selector: 'app-openfolders',
  standalone: true,
  imports: [IconComponent, CommonModule, MatTooltipModule],
  templateUrl: './openfolders.component.html',
  styleUrl: './openfolders.component.scss',
  // changeDetection: ChangeDetectionStrategy.OnPush,
})
export class OpenfoldersComponent implements OnInit, OnDestroy, OnChanges {
  @Input() changeF = false;
  @Input() activeSection?: SectionRes;
  @Input() nBundleid?: string;
  @Output() readonly changeTab = new EventEmitter<string>();

  folders: OpenFolderItem[] = [];

  private evsubscription?: Subscription;

  constructor(public mfs: MyfileService, private readonly cs: CommunicationService) {}

  ngOnInit(): void {
    this.evsubscription = this.cs.functionCalled$.subscribe((data: any) => {
      if (data?.type !== 'UPDATE-FOLDER') {
        return;
      }

      const folderToUpdate = this.folders.find((folder) => String(folder.id) === String(data.nBundleid));
      if (!folderToUpdate?.path?.length) {
        return;
      }

      folderToUpdate.path[folderToUpdate.path.length - 1] = String(data.cBundlename ?? '');
    });
  }

  ngOnDestroy(): void {
    this.evsubscription?.unsubscribe();
  }

  ngOnChanges(_changes: SimpleChanges): void {
    const activeId = this.nBundleid;
    this.folders.forEach((folder) => {
      folder.isactive = activeId ? String(folder.id) === String(activeId) : false;
    });
  }

  onDragOver(event: DragEvent) {
    event.preventDefault();
  }

  onDrop(event: DragEvent, parent: HTMLElement) {
    this.mfs.isfolderdraging = false;
    event.preventDefault();
    const data = event.dataTransfer?.getData('text');
    if (data) {
      const item = JSON.parse(data) as OpenFolderItem;
      const existing = this.folders.find((folder) => String(folder.id) === String(item.id));
      if (!existing) {
        this.folders.push(item);
      }

      this.folders.forEach((folder) => {
        folder.isactive = String(folder.id) === String(item.id);
      });

      this.changeTab.emit(`OPEN_F_${item.id}`);
      // You can now process the dropped item
    }
    setTimeout(() => {
      if (parent.scrollWidth > parent.clientWidth) {
        parent.scrollLeft = parent.scrollWidth - parent.clientWidth;
      }
    }, 10);

  }

  onDragEnd(_event: DragEvent) {
    this.folders = [];
  }

  changeFolder(folder: OpenFolderItem) {
    this.folders.forEach((f) => (f.isactive = String(f.id) === String(folder.id)));
    folder.isactive = true;
    this.changeTab.emit(`OPEN_F_${folder.id ?? 0}`);
  }

  closeFolder(folder: OpenFolderItem) {
    if (this.folders.length === 1) {
      this.folders = [];
      this.changeTab.emit('OPEN_F_0');
    } else {
      this.folders = this.folders.filter((f) => String(f.id) !== String(folder.id));
      if (!this.folders.length) {
        const rootPath = this.activeSection?.cFolder ? [this.activeSection.cFolder] : [];
        this.folders = [{ id: 0, path: rootPath, isactive: true }];
      }
      this.changeFolder(this.folders.length ? this.folders[0] : { id: 0, path: [], isactive: true });
    }
  }

}
