import { ChangeDetectorRef, Component, EventEmitter, Input, Output, ViewChild } from '@angular/core';
import { CdkVirtualScrollViewport, ScrollingModule } from '@angular/cdk/scrolling';
import { NgScrollbarModule } from 'ngx-scrollbar';
import { MyfileService } from '../../../services/myfile/myfile.service';
import { bundleRes, ExampleFlatNode, SharedByUser } from '../../../interfaces/myfile.interface';
import { BehaviorSubject, Subject } from 'rxjs';
import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { IconComponent } from '../../icon/icon.component';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MatFormFieldModule } from '@angular/material/form-field';
import { SectionRes } from '../../../../adminpanel/interfaces/bundlemanage.interface';
import { MatDialog } from '@angular/material/dialog';
import { CommunicationService } from '../../../services/communication/communication.service';
import { MatMenuModule, MatMenuTrigger } from '@angular/material/menu';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { PaginationService } from '../../../../adminpanel/services/pagination/pagination.service';
import { FormsModule } from '@angular/forms';
import { SharewithteamComponent } from '../sharewithteam/sharewithteam.component';
import { presentDocType } from '../../../../presentation/interfaces/presentsetup';
import { HyperlinkService } from '../../../../adminpanel/services/hyperlink/hyperlink.service';
import { HeaderService } from '../../../../core/services/header/header.service';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { finalFilterList } from '../../../interfaces/filter.interface';
import { FoldersComponent } from "../folders/folders.component";
import { SECTION_FOLDER_TYPES } from '../../../interfaces/section.interface';


@Component({
  selector: 'all-section',
  standalone: true,
  imports: [CommonModule, ScrollingModule, NgScrollbarModule, IconComponent, MatCheckboxModule, MatTooltipModule,
    MatFormFieldModule, MatMenuModule, FormsModule, FoldersComponent, TranslateModule],
  templateUrl: './all-section.component.html',
  styleUrl: './all-section.component.scss'
})
export class AllSectionComponent {

  public readonly SectionFolderTypes = SECTION_FOLDER_TYPES;



  @ViewChild(CdkVirtualScrollViewport) viewport: CdkVirtualScrollViewport;
  @ViewChild('shareteam') shareteam: SharewithteamComponent;
  @Input() menuTrigger: MatMenuTrigger;
  @Input() isSepcomponent: boolean;
  @Input() assignPopup: boolean;
  nSectionid: string;
  @Input() cFoldertype: string;
  @Input() nCaseid: string;
  @Input() isadmin: boolean;
  @Input() nBundleid: string;
  @Output() nBundleidChange = new EventEmitter<string>();
  @Input() changeF: boolean;
  @Input() cutCopyType: string = '';
  @Input() Allsectionlist: any[] = [];
  @Input() isIndividual: boolean = false;
  @Input() selectedIDs: string[] = [];
  @Input() detail: { nUPid: string, isadmin: boolean, isChooser: boolean };

  @Input() onFileEvent: Subject<toolEvents>;
  jfileFilter: finalFilterList[] = [];
  @Output() changeFolder: EventEmitter<any> = new EventEmitter();
  @Output() changeSectionAll: EventEmitter<SectionRes> = new EventEmitter();
  @Output() getSelection: EventEmitter<string> = new EventEmitter();
  @Output() isEmptyevent: EventEmitter<any> = new EventEmitter();
  activeBundle: bundleRes;
  loading: boolean = true;
  checkedusers: number = 0;
  shareexpand: boolean = false;
  @Input() TREE_DATA: ExampleFlatNode[] = [];
  @Output() TREE_DATAChange = new EventEmitter<ExampleFlatNode[]>();
  @Input() LAST_TREE_DATA_STAT: ExampleFlatNode[] = [];
  @Output() LAST_TREE_DATA_STATChange = new EventEmitter<ExampleFlatNode[]>();

  dataSource = new BehaviorSubject<any[]>(this.TREE_DATA);
  isCopy: boolean = false;
  sharedByuser: SharedByUser[] = [];
  viewSection: SharedByUser;


  @Input() selectedBundles: string[] = [];
  @Input() nSelectedFolderid: Array<{ id: string, pid: string }> = [];

  @Input() presentDocType: presentDocType;

  @Input() searchedBundles: string[];
  @Output() searchedBundlesChange = new EventEmitter<string[]>();
  @Input() isFolderLoading: boolean = false;
  @Output() isFolderLoadingChange = new EventEmitter<boolean>();
  @Input() isPreview: boolean = false;
  @Output() isPreviewChange = new EventEmitter<boolean>();

  bundlecount: number = 0;

  allSectionViewPort: boolean = false;
  @Input() loadFolderChild: Subject<any>;

  constructor(
    public readonly myfileS: MyfileService,
    private readonly cdr: ChangeDetectorRef,
    private readonly dialog: MatDialog,
    private readonly cs: CommunicationService,
    private readonly cf: CommonfunctionService,
    private readonly paginationS: PaginationService,
    private readonly hyperlinkService: HyperlinkService,
    private readonly hs: HeaderService
  ) {}

  async changeSection(x: SectionRes): Promise<void> {
    if (!x?.isActive) return;

    this.allSectionViewPort = true;

    if (this.nSectionid === x.nSectionid) {
      this.nSectionid = null;
      this.nBundleid = null;
      this.nBundleidChange.emit(this.nBundleid);
    } else {
      this.nSectionid = x.nSectionid;
    }

    this.cdr.detectChanges();
    this.changeSectionAllEmitter(x);
  }


  changeFolderEmitter(data: any): void {
    this.changeFolder.emit(data);
  }


  changeSectionAllEmitter(data: SectionRes): void {
    this.changeSectionAll.emit(data);
  }

  getSelectionEmitter(data: string): void {
    this.getSelection.emit(data);
  }

  isEmptyeventEmitter(data: any): void {
    this.isEmptyevent.emit(data);
  }

  onTreeDataChange(data: ExampleFlatNode[]): void {
    this.TREE_DATA = data;
    this.TREE_DATAChange.emit(this.TREE_DATA);
  }

  onLastTreeDataStatChange(data: ExampleFlatNode[]): void {
    this.LAST_TREE_DATA_STAT = data;
    this.LAST_TREE_DATA_STATChange.emit(this.LAST_TREE_DATA_STAT);
  }

  onIspreviewChange(data: boolean): void {
    this.isPreview = data;
    this.isPreviewChange.emit(this.isPreview);
  }

  onsearchedBundlesChange(data: string[]): void {
    this.searchedBundles = data;
    this.searchedBundlesChange.emit(this.searchedBundles);
  }
}

