  recentFileIds: string[] = []; // recently present ids for multi file open in presentation 
  recentChooseDocs: { id: string, bid: string }[] = [] // recent files from choose-docs in presentation 

  isElasticSearch: boolean;

  nStarttabid: string;
  nEndtabid: string;
  showfilter: boolean = false;
