  async OnFileToExplorerEvent(event) {
    const ev = event || {};
    if (ev.event?.includes('OPEN_FOLDER')) {
      await this.handleOpenFolderEvent(ev);
      return;
    }

    if (ev.event === FILEEXPLORER_EVENTS.VIEW_LINK_RESULT) {
      await this.handleViewLinkResult(ev);
      return;
    }

    this.OnFileEvent.emit(ev);
  }

  private async handleOpenFolderEvent(event: any) {
    const bundleId = event?.data?.nBundleid;

    if (this.hs.isGlobalSearch) {
      if (bundleId) {
        const idx = this.brdcrumbsearch.findIndex(e => e.nBundleid == bundleId);
        if (idx === -1) this.brdcrumbsearch.push({ nBundleid: bundleId, cBundlename: event?.data?.cName });
      } else {
        this.brdcrumbsearch = [];
      }
    }

    const node = this.folderCom.getBundleNode(bundleId);
    if (node) {
      if (this.cFoldertype === 'ALL') {
        this.loadFolderChild$.next({ data: node });
      } else {
        this.folderCom.loadChildren(node);
      }
      return;
    }

    const nBundleid = bundleId;
    if (this.fileCom.nBundleid !== nBundleid) {
      this.fileCom.nBundleid = nBundleid;
      this.fileCom.getFileList(1);
      if (bundleId && event?.data?.cName && !this.hs.isGlobalSearch) {
        const index = this.brdcrumb.findIndex(e => e.nBundleid == bundleId);
        if (index === -1) this.brdcrumb.push({ nBundleid: bundleId, cBundlename: event?.data?.cName });
      }
    }
  }

  private async handleViewLinkResult(event: any) {
    const id = event?.data?.nBundledetailid;
    if (!id) return;
    const filedata = await this.mfs.getFiledata({ nBundledetailid: id });
    if (filedata) {
      this.viewFile(filedata, event?.data?.page);
    }
  }

  requiredSelectedDocs(data?: { removedDocs: string[], files: any[] }) {

    try {
      const fldrids = this.nSelectedFolderid;
      let fileids = this.nSelectedFilesid;

      if (this.recentChooseDocs.length) {
        this.nSelectedFilesid = [...this.nSelectedFilesid, ...this.recentChooseDocs]
        this.recentChooseDocs = [];

      }
      if (data?.removedDocs?.length) {
        this.nSelectedFilesid = this.nSelectedFilesid.filter(e => !data.removedDocs.includes(e.id));
        fileids = this.nSelectedFilesid;
        this.recentChooseDocs = this.recentChooseDocs.filter(e => !data.removedDocs.includes(e.id));
        this.fileCom.selectedBundleDetails = this.fileCom.selectedBundleDetails?.filter(id => !data.removedDocs.includes(id)) || [];
        this.fileCom.fileList.forEach((x) => {
          x.cIscheck = data.removedDocs.includes(x.nBundledetailid) ? false : x.cIscheck
        })
      }

      if (data?.files) {
        this.recentChooseDocs = data.files.map(({ nBundledetailid, nBundleid }) => ({ id: nBundledetailid, bid: nBundleid || null })) || [];
      }

      if (this.recentChooseDocs.length) {
        fileids = fileids.concat(this.recentChooseDocs);
      }

      let uniqueData = fileids.filter((item, index, self) =>
        index === self.findIndex((t) => t.id === item.id)
      );

      if (this.nTypeid) {
        this.selectedBundleDetails = uniqueData.map((a) => a.id);
      }
      if (this.fileCom?.selectedBundleDetails?.length) {
        uniqueData = this.mergeSelectedBundleDetails(uniqueData);
      }

      if (this.folderCom?.selectedBundles?.length) {
        this.folderCom.selectedBundles.forEach(id => {
          if (!fldrids.some(i => i.id == id)) {
            fldrids.push({ id: id, pid: null })
          }
        });
      }

      this.nSelectedFilesid = this.nSelectedFilesid.filter(
        (value, index, self) =>
          index === self.findIndex((t) => t.id === value.id && t.bid === value.bid)
      );

      this.handleSelection.emit({ fldrids, fileids: uniqueData });
    } catch (error) {
      const msg = ErrorHandlerUtil.getErrorMessage(error);
      this.tost.error(msg);
    }
  }

    private mergeSelectedBundleDetails(uniqueData: any[]): any[] {
      if (!this.fileCom?.selectedBundleDetails?.length) return uniqueData;

      if (!uniqueData.length) {
        return this.fileCom.selectedBundleDetails.map(id => ({ id: id, bid: null }));
      }

      this.fileCom.selectedBundleDetails.forEach(id => {
        if (!uniqueData.some(i => i.id == id)) {
          uniqueData.push({ id: id, bid: null });
        }
      });

      return uniqueData;
    }

