import { Component, EventEmitter, Input, OnChanges, OnInit, Output, SimpleChanges, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { IconComponent } from '../../icon/icon.component';
import { ButtonComponent } from '../../button/button.component';
import { ToolbarService } from '../../../../rt/services/toolbar/toolbar.service';
import { SessionListItem } from '../../../../rt/interfaces/toolbar.interface';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { RealtimeService } from '../../../../rt/services/realtime/realtime.service';
import { NgScrollbarModule } from 'ngx-scrollbar';

@Component({
  selector: 'transcript-session-list',
  standalone: true,
  imports: [CommonModule, TranslateModule, IconComponent, ButtonComponent, NgScrollbarModule],
  templateUrl: './transcript-session-list.component.html',
})
export class TranscriptSessionListComponent implements OnInit, OnChanges {
  @Input() nCaseid: string;

  /** Double-click: open in individual doc (new window) */
  @Output() onSessionOpen = new EventEmitter<{ nSesid: string; cName: string; isTranscript: boolean }>();

  /**
   * Single click: show in right preview panel.
   * `isTranscript` tells the parent whether this session has a published transcript
   * (so it should route to <transcript-viewer>) or is still a raw realtime feed
   * (so it should route to <feed-display>). Derived from the session-list flags —
   * more authoritative than sessionDetail.isTrans, which the SP currently returns
   * as false even for published sessions.
   */
  @Output() onSessionPreview = new EventEmitter<{ nSesid: string; cName: string; isTranscript: boolean }>();

  sessions: SessionListItem[] = [];
  isCollapsed: boolean = false;
  isLoading: boolean = false;
  selectedSesid: string = '';

  /** Map of nSesid → total page count (lazily loaded from session detail) */
  pageCounts: Record<string, number> = {};

  private nUserid: string = '';

  constructor(
    private toolbarService: ToolbarService,
    private secureStorage: SecureStorageService,
    private realtimeService: RealtimeService,
    private cdr: ChangeDetectorRef,
  ) {}

  async ngOnInit(): Promise<void> {
    this.nUserid = await this.secureStorage.getUserId();
    await this.loadSessions();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['nCaseid'] && !changes['nCaseid'].firstChange) {
      // Reset local selection so the auto-preview runs again for the new case.
      this.selectedSesid = '';
      this.loadSessions();
    }
  }

  async loadSessions(): Promise<void> {
    if (!this.nCaseid || !this.nUserid) return;

    this.isLoading = true;
    this.cdr.detectChanges();

    try {
      const res = await this.toolbarService.getSessionList(this.nCaseid, this.nUserid);
      this.sessions = (res || [])
        .filter(s => s.cStatus !== 'R')
        .sort((a, b) => {
          const dateA = new Date(a.dStartDt).getTime();
          const dateB = new Date(b.dStartDt).getTime();
          return dateA - dateB;
        });
      this.loadPageCounts();
    } catch (err) {
      console.error('Failed to load transcript sessions:', err);
      this.sessions = [];
    } finally {
      this.isLoading = false;
      this.cdr.detectChanges();
    }
  }

  /**
   * Lazily fetch total page count for each session via sessionDetail.maxNumber.
   * Runs in parallel; updates the view as each resolves.
   */
  private loadPageCounts(): void {
    this.pageCounts = {};
    for (const session of this.sessions) {
      this.realtimeService.getSessionDetail(session.nSesid, this.nUserid)
        .then(detail => {
          if (detail?.maxNumber != null) {
            this.pageCounts[session.nSesid] = detail.maxNumber;
            this.cdr.detectChanges();
          }
        })
        .catch(err => console.warn('Could not load page count for session', session.nSesid, err));
    }
  }

  /** Single click: preview in right panel */
  previewSession(session: SessionListItem): void {
    this.selectedSesid = session.nSesid;
    this.onSessionPreview.emit({
      nSesid: session.nSesid,
      cName: session.cName,
      // A session counts as "has a published transcript" iff both flags are true.
      // isTranscript alone isn't sufficient — the column gets set during upload
      // before the publish pipeline finishes copying files.
      isTranscript: !!session.isTranscript && !!session.isUploaded,
    });
  }

  /** Double click: open in individual doc */
  openSession(session: SessionListItem): void {
    this.onSessionOpen.emit({
      nSesid: session.nSesid,
      cName: session.cName,
      isTranscript: !!session.isTranscript && !!session.isUploaded,
    });
  }

  toggleCollapse(): void {
    this.isCollapsed = !this.isCollapsed;
  }

  /** Two source-of-truth signals for "this session has a published transcript":
   *
   *  1. `cStatus = 'P'` — set by the RT publish path
   *     (`et_transcript_publish`) when a live session is finalised into a
   *     transcript. That SP also flips `isTranscript = true` and
   *     `isUploaded = true`, so it covers both signals at once.
   *  2. `isTranscript && isUploaded` — set by the direct transcript-file
   *     upload path. THAT path does NOT touch `cStatus`, so a transcript
   *     uploaded as a file stays at `cStatus = 'C'` (or whatever the
   *     upload set) and the old switch-on-cStatus rendered it as
   *     "Draft" forever, even though the transcript was fully usable.
   *     The rest of this component already treats
   *     `isTranscript && isUploaded` as the canonical "has a published
   *     transcript" check (see `previewSession` / `openSession`); the
   *     badge needs to match.
   *
   *  Precedence here matches the rest of the app: if EITHER signal says
   *  published, render Published. Live ('R') and Draft fall through. */
  getStatusLabel(session: SessionListItem): string {
    if (session.cStatus === 'P' || (!!session.isTranscript && !!session.isUploaded)) {
      return 'Published';
    }
    if (session.cStatus === 'R') return 'Live';
    return 'Draft';
  }

  getStatusBadgeClass(session: SessionListItem): string {
    if (session.cStatus === 'P' || (!!session.isTranscript && !!session.isUploaded)) {
      return 'bg-green-100 text-green-700';
    }
    if (session.cStatus === 'R') return 'bg-blue-100 text-blue-700';
    return 'bg-amber-100 text-amber-700';
  }
}
